def prime_fib(n: int):
    def is_prime(x: int) -> bool:
        if x <= 1:
            return False
        if x <= 3:
            return True
        if x % 2 == 0 or x % 3 == 0:
            return False
        i = 5
        while i * i <= x:
            if x % i == 0 or x % (i + 2) == 0:
                return False
            i += 6
        return True

    def fibonacci_sequence():
        a, b = 0, 1
        while True:
            yield a
            a, b = b, a + b

    fib_generator = fibonacci_sequence()
    prime_fib_count = 0

    while True:
        fib_number = next(fib_generator)
        if is_prime(fib_number):
            prime_fib_count += 1
            if prime_fib_count == n:
                return fib_number
